409	          <div className="assignee-card"><span className="avatar avatar-self">AM</span><span><small>Assigned to</small><strong>Alex Morgan</strong></span><button aria-label="Change assignee"><Icon name="person" /></button></div>
410	        </aside>
411	      </main>
412	    </div>
