 12	async function auditTargets(page: Page): Promise<Audit> {
 13	  return page.evaluate(() => {
 14	    const selector = "button, a, input, select, textarea, [role='button'], [tabindex]:not([tabindex='-1'])";
 15	    const nodes = Array.from(document.querySelectorAll<HTMLElement>(selector)).filter((node) => {
 16	      const style = getComputedStyle(node);
 17	      const rect = node.getBoundingClientRect();
 18	      return style.display !== "none" && style.visibility !== "hidden" && rect.width > 0 && rect.height > 0;
 19	    });
 20	    const measurements = nodes.map((node) => {
 21	      const rect = node.getBoundingClientRect();
 22	      return {
 23	        label: node.getAttribute("aria-label") || node.textContent?.trim().replace(/\s+/g, " ").slice(0, 48) || node.tagName,
 24	        width: Math.round(rect.width * 10) / 10,
 25	        height: Math.round(rect.height * 10) / 10,
 26	      };
 27	    });
 28	    return {
 29	      viewport: document.documentElement.clientWidth,
 30	      document: document.documentElement.scrollWidth,
 31	      minimumWidth: Math.min(...measurements.map((item) => item.width)),
 32	      minimumHeight: Math.min(...measurements.map((item) => item.height)),
 33	      count: measurements.length,
 34	      offenders: measurements.filter((item) => item.width < 44 || item.height < 44),
 35	    };
 36	  });
 37	}
