 26	  const runId = useRef(0);
 27	  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
 28	  const alive = useRef(true);
 29	
 30	  const act = useRef(action);
 31	  const fail = useRef(onError);
 32	
 33	  useEffect(() => {
 34	    act.current = action;
 35	    fail.current = onError;
 36	  });
 37	
 38	  const clear = useCallback(() => {
 39	    if (timer.current) {
 40	      clearTimeout(timer.current);
 41	      timer.current = null;
 42	    }
 43	  }, []);
 44	
 45	  const reset = useCallback(() => {
 46	    runId.current += 1;
 47	    clear();
 48	    phase.current = "idle";
 49	    setStatus("idle");
 50	  }, [clear]);
 51	
 52	  const run = useCallback(() => {
 53	    if (phase.current === "pending") return;
 54	
 55	    clear();
 56	    const id = ++runId.current;
 57	    phase.current = "pending";
 58	    setStatus("pending");
 59	
 60	    const settle = (next: "success" | "error") => {
 61	      if (!alive.current || id !== runId.current) return;
 62	      clear();
 63	      phase.current = next;
 64	      setStatus(next);
 65	      timer.current = setTimeout(() => {
 66	        if (!alive.current || id !== runId.current) return;
 67	        phase.current = "idle";
 68	        setStatus("idle");
 69	      }, resetAfter);
 70	    };
 71	
 72	    Promise.resolve()
 73	      .then(() => act.current())
 74	      .then(
 75	        () => settle("success"),
 76	        (error: unknown) => {
 77	          fail.current?.(error);
 78	          settle("error");
 79	        },
 80	      );
 81	  }, [clear, resetAfter]);
 82	
 83	  useEffect(() => {
 84	    alive.current = true;
 85	    return () => {
 86	      alive.current = false;
 87	      clear();
 88	    };
 89	  }, [clear]);
 90	
 91	  return {
 92	    status,
 93	    run,
 94	    reset,
 95	    pending: status === "pending",
 96	  };
